package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class RootBoundedBusinessScopeTest {
 @Test public void exactlySixPhaseClaimsAndNoOverrun(){assertTrue(RootBoundedBusinessScope.ACTIVE);assertEquals(3,RootBoundedBusinessScope.MAX_PER_PHASE);assertEquals(6,RootBoundedBusinessScope.MAX_FRAMES);Set<String> slots=new HashSet<>();for(var p:NativeRewardCardSession.Phase.values())for(int i=1;i<=3;i++)assertTrue(slots.add(RootBoundedBusinessScope.slot(p,i)));assertEquals(Set.of("BEFORE_1","BEFORE_2","BEFORE_3","AFTER_1","AFTER_2","AFTER_3"),slots);for(int i:new int[]{Integer.MIN_VALUE,-1,0,4,Integer.MAX_VALUE}){assertFalse(RootBoundedBusinessScope.validIndex(i));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.slot(NativeRewardCardSession.Phase.BEFORE,i));}assertThrows(SecurityException.class,()->RootBoundedBusinessScope.slot(null,1));}
 @Test public void halfOpenAdmissionKeepsOriginal180s(){long s=RootBoundedBusinessScope.STARTS_UTC,e=RootBoundedBusinessScope.EXPIRES_UTC;assertFalse(RootBoundedBusinessScope.current(s-1));assertTrue(RootBoundedBusinessScope.current(s));assertTrue(RootBoundedBusinessScope.current(e-1));assertFalse(RootBoundedBusinessScope.current(e));assertTrue(RootBoundedBusinessScope.admissionCurrent(e-180001));assertFalse(RootBoundedBusinessScope.admissionCurrent(e-180000));assertEquals(181000,RootBoundedBusinessScope.sessionDeadline(1000,s));}
 @Test public void phaseDeadlineCannotExceedParentOrUtc(){long u=RootBoundedBusinessScope.STARTS_UTC;assertEquals(91000,RootBoundedBusinessScope.deadline(1000,u,181000));assertEquals(181000,RootBoundedBusinessScope.deadline(101000,u+100000,181000));assertEquals(1500,RootBoundedBusinessScope.deadline(1000,u,1500));assertEquals(1001,RootBoundedBusinessScope.deadline(1000,RootBoundedBusinessScope.EXPIRES_UTC-1,181000));}
 @Test public void invalidClocksFailClosed(){long u=RootBoundedBusinessScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootBoundedBusinessScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.sessionDeadline(1,RootBoundedBusinessScope.EXPIRES_UTC));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.deadline(-1,u,100));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.deadline(Long.MAX_VALUE,u,Long.MAX_VALUE));}
 @Test public void onlyNewNamespaceAndFixedActionSlots()throws Exception{assertNotEquals(RootBoundedBusinessScope.DIRECTORY,RootImageSeriesScope.DIRECTORY);assertNotEquals(RootBoundedBusinessScope.DIRECTORY,RootFamilyDiagnosticProfile.DIRECTORY);assertNotEquals(RootBoundedBusinessScope.DIRECTORY,AutonomousRewardCardScope.DIRECTORY);assertNotEquals(RootBoundedBusinessScope.DIRECTORY,RootCaptureScope.PREFLIGHT_DIRECTORY);assertThrows(SecurityException.class,()->RootBoundedBusinessScope.store(null,NativeRewardCardSession.Phase.BEFORE,1));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.burnAction(Path.of("unused"),"BEFORE","safe"));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.burnAction(Path.of("unused"),"../TAP","safe"));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.burnAction(null,"TAP","safe"));}
 @Test public void badClaimsAndOversizedMetadataNeverWrite()throws Exception{var store=RootBoundedBusinessScope.store(Path.of("unused"),NativeRewardCardSession.Phase.BEFORE,1);assertThrows(SecurityException.class,()->store.burn("invalid","safe"));assertThrows(SecurityException.class,()->store.burn("11111111-1111-1111-1111-111111111111",null));assertThrows(SecurityException.class,()->store.burn("11111111-1111-1111-1111-111111111111","x".repeat(2049)));assertThrows(SecurityException.class,()->RootBoundedBusinessScope.burnAction(Path.of("unused"),"RETURN",null));}
 @Test public void durablePrimitiveHasNoRecoveryOrTruncate()throws Exception{Path p=Path.of("../app/src/main/java/com/aliothmoon/maafw/once/RootBoundedBusinessScope.java");if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once/RootBoundedBusinessScope.java");String s=Files.readString(p);assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("c.force(true)"));assertFalse(s.contains("delete("));assertFalse(s.contains("TRUNCATE_EXISTING"));assertTrue(s.contains("maxFrames=6 maxPerPhase=3 maxTap=1 maxReturn=1"));}
}
